import {useEffect, useState} from 'react';
import Header from '../components/Header';
import Footer from '../components/Footer';
import '../styles/MerchAdmin.css';

const API_URL = 'http://localhost:5000/api/items';

const GENRES = ['femme', 'homme', 'neutre'];
const CATEGORIES = [
    'pantalon',
    'robe',
    't-shirt',
    'chemise',
    'blouse',
    'polo',
    'pull',
    'sweat',
    'chaussures',
    'ceinture',
    'manteau'
];

const newItemTemplate = {
    name: '',
    price: '',
    cover: '',
    size: '',
    comfort: '',
    onSale: false,
    description: '',
    gender: 'neutre',
    category: 't-shirt',
    stock: 0
};

function MerchAdmin() {
    const [items, setItems] = useState([]);
    const [newItem, setNewItem] = useState(newItemTemplate);
    const [feedback, setFeedback] = useState('');
    const [loading, setLoading] = useState(false);

    async function loadItems() {
        setLoading(true);
        try {
            const response = await fetch(API_URL);
            const data = await response.json();
            setItems(Array.isArray(data) ? data : []);
        } catch (error) {
            setFeedback('Impossible de charger les articles.');
        } finally {
            setLoading(false);
        }
    }

    useEffect(() => {
        loadItems();
    }, []);

    function updateLocalItem(id, field, value) {
        setItems((current) =>
            current.map((item) => (item.id === id ? {...item, [field]: value} : item))
        );
    }

    async function addItem(event) {
        event.preventDefault();
        setFeedback('');

        const payload = {
            ...newItem,
            price: Number(newItem.price),
            comfort: newItem.comfort === '' ? null : Number(newItem.comfort),
            stock: Number(newItem.stock)
        };

        const response = await fetch(API_URL, {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify(payload)
        });

        if (!response.ok) {
            const error = await response.json();
            setFeedback(error.error || 'Erreur lors de la creation.');
            return;
        }

        setNewItem(newItemTemplate);
        setFeedback('Article ajoute.');
        await loadItems();
    }

    async function saveItem(item) {
        setFeedback('');

        const payload = {
            ...item,
            price: Number(item.price),
            comfort: item.comfort === '' || item.comfort === null ? null : Number(item.comfort),
            stock: Number(item.stock)
        };

        const response = await fetch(`${API_URL}/${item.id}`, {
            method: 'PUT',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify(payload)
        });

        if (!response.ok) {
            const error = await response.json();
            setFeedback(error.error || 'Erreur lors de la mise a jour.');
            return;
        }

        setFeedback(`Article #${item.id} mis a jour.`);
        await loadItems();
    }

    async function saveStock(item) {
        setFeedback('');
        const response = await fetch(`${API_URL}/${item.id}/stock`, {
            method: 'PATCH',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({stock: Number(item.stock)})
        });

        if (!response.ok) {
            const error = await response.json();
            setFeedback(error.error || 'Erreur lors de la mise a jour du stock.');
            return;
        }

        setFeedback(`Stock de l'article #${item.id} mis a jour.`);
        await loadItems();
    }

    async function removeItem(id) {
        setFeedback('');
        const response = await fetch(`${API_URL}/${id}`, {method: 'DELETE'});

        if (!response.ok) {
            const error = await response.json();
            setFeedback(error.error || 'Erreur lors de la suppression.');
            return;
        }

        setFeedback(`Article #${id} supprime.`);
        await loadItems();
    }

    return (
        <div className="page">
            <Header/>
            <main className="page__content merch-admin">
                <h1 className="page__title">Gestion merch</h1>

                <section className="page__section merch-admin__panel">
                    <h2 className="merch-admin__subtitle">Ajouter un article</h2>
                    <form className="merch-admin__form" onSubmit={addItem}>
                        <input
                            className="input"
                            placeholder="Nom"
                            value={newItem.name}
                            onChange={(event) => setNewItem({...newItem, name: event.target.value})}
                            required
                        />
                        <input
                            className="input"
                            type="number"
                            step="0.01"
                            placeholder="Prix"
                            value={newItem.price}
                            onChange={(event) => setNewItem({...newItem, price: event.target.value})}
                            required
                        />
                        <input
                            className="input"
                            type="number"
                            placeholder="Stock"
                            value={newItem.stock}
                            onChange={(event) => setNewItem({...newItem, stock: event.target.value})}
                            required
                        />
                        <select
                            className="input"
                            value={newItem.gender}
                            onChange={(event) => setNewItem({...newItem, gender: event.target.value})}
                        >
                            {GENRES.map((genre) => (
                                <option key={genre} value={genre}>{genre}</option>
                            ))}
                        </select>
                        <select
                            className="input"
                            value={newItem.category}
                            onChange={(event) => setNewItem({...newItem, category: event.target.value})}
                        >
                            {CATEGORIES.map((categorie) => (
                                <option key={categorie} value={categorie}>{categorie}</option>
                            ))}
                        </select>
                        <input
                            className="input"
                            placeholder="Taille"
                            value={newItem.size}
                            onChange={(event) => setNewItem({...newItem, size: event.target.value})}
                        />
                        <input
                            className="input"
                            type="number"
                            placeholder="Confort"
                            value={newItem.comfort}
                            onChange={(event) => setNewItem({...newItem, comfort: event.target.value})}
                        />
                        <input
                            className="input"
                            placeholder="URL image (cover)"
                            value={newItem.cover}
                            onChange={(event) => setNewItem({...newItem, cover: event.target.value})}
                        />
                        <textarea
                            className="input merch-admin__textarea"
                            placeholder="Description"
                            value={newItem.description}
                            onChange={(event) => setNewItem({...newItem, description: event.target.value})}
                        />
                        <label className="merch-admin__checkbox">
                            <input
                                type="checkbox"
                                checked={newItem.onSale}
                                onChange={(event) => setNewItem({...newItem, onSale: event.target.checked})}
                            />
                            En promo
                        </label>
                        <button className="btn" type="submit">Ajouter</button>
                    </form>
                </section>

                <section className="page__section merch-admin__panel">
                    <h2 className="merch-admin__subtitle">Liste des articles</h2>
                    {loading ? <p>Chargement...</p> : null}
                    {feedback ? <p className="merch-admin__feedback">{feedback}</p> : null}

                    <div className="merch-admin__list">
                        {items.map((item) => (
                            <article className="merch-admin__item card" key={item.id}>
                                <div className="merch-admin__row">
                                    <input
                                        className="input"
                                        value={item.name || ''}
                                        onChange={(event) => updateLocalItem(item.id, 'name', event.target.value)}
                                    />
                                    <input
                                        className="input"
                                        type="number"
                                        step="0.01"
                                        value={item.price ?? 0}
                                        onChange={(event) => updateLocalItem(item.id, 'price', event.target.value)}
                                    />
                                    <input
                                        className="input"
                                        type="number"
                                        value={item.stock ?? 0}
                                        onChange={(event) => updateLocalItem(item.id, 'stock', event.target.value)}
                                    />
                                </div>

                                <div className="merch-admin__row">
                                    <select
                                        className="input"
                                        value={item.gender || 'neutre'}
                                        onChange={(event) => updateLocalItem(item.id, 'gender', event.target.value)}
                                    >
                                        {GENRES.map((genre) => (
                                            <option key={genre} value={genre}>{genre}</option>
                                        ))}
                                    </select>
                                    <select
                                        className="input"
                                        value={item.category || 't-shirt'}
                                        onChange={(event) => updateLocalItem(item.id, 'category', event.target.value)}
                                    >
                                        {CATEGORIES.map((categorie) => (
                                            <option key={categorie} value={categorie}>{categorie}</option>
                                        ))}
                                    </select>
                                    <input
                                        className="input"
                                        placeholder="Taille"
                                        value={item.size || ''}
                                        onChange={(event) => updateLocalItem(item.id, 'size', event.target.value)}
                                    />
                                </div>

                                <div className="merch-admin__row">
                                    <input
                                        className="input"
                                        type="number"
                                        placeholder="Confort"
                                        value={item.comfort ?? ''}
                                        onChange={(event) => updateLocalItem(item.id, 'comfort', event.target.value)}
                                    />
                                    <input
                                        className="input"
                                        placeholder="URL image (cover)"
                                        value={item.cover || ''}
                                        onChange={(event) => updateLocalItem(item.id, 'cover', event.target.value)}
                                    />
                                </div>

                                <textarea
                                    className="input merch-admin__textarea"
                                    placeholder="Description"
                                    value={item.description || ''}
                                    onChange={(event) => updateLocalItem(item.id, 'description', event.target.value)}
                                />

                                <label className="merch-admin__checkbox">
                                    <input
                                        type="checkbox"
                                        checked={Boolean(item.onSale)}
                                        onChange={(event) => updateLocalItem(item.id, 'onSale', event.target.checked)}
                                    />
                                    En promo
                                </label>

                                <div className="merch-admin__actions">
                                    <button className="btn" onClick={() => saveItem(item)}>Sauvegarder</button>
                                    <button className="btn btn__ghost" onClick={() => saveStock(item)}>Changer stock</button>
                                    <button className="btn btn__ghost" onClick={() => removeItem(item.id)}>Supprimer</button>
                                </div>
                            </article>
                        ))}
                    </div>
                </section>
            </main>
            <Footer/>
        </div>
    );
}

export default MerchAdmin;
